head.b:skin:
:root{--bg:#f6f4ee;--paper:#fff;--ink:#23271f;--sub:#5d6356;--line:#e2ded2;--forest:#2f4a3a;--moss:#6f8a5b;--lake:#4f7f93}
*{box-sizing:border-box}html,body{margin:0}
body{background:var(--bg);color:var(--ink);font:16px/1.75 'Noto Sans KR',system-ui,sans-serif;-webkit-font-smoothing:antialiased}
a{color:inherit}img{max-width:100%;height:auto}
h1,h2,h3{font-family:'Noto Serif KR',serif;line-height:1.35;text-wrap:balance;margin:0 0 .6em}
.top{position:sticky;top:0;z-index:9;background:rgba(246,244,238,.94);backdrop-filter:blur(6px);border-bottom:1px solid var(--line)}
.top .in{max-width:1120px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 20px;flex-wrap:wrap}
.logo{font-family:'Noto Serif KR',serif;font-weight:700;font-size:22px;text-decoration:none;color:var(--forest);letter-spacing:.02em}
.logo small{display:block;font:500 11px 'Noto Sans KR';color:var(--sub);letter-spacing:.12em}
nav{display:flex;gap:4px;flex-wrap:wrap}
nav a{text-decoration:none;font-size:15px;padding:8px 12px;border-radius:999px;color:var(--ink)}
nav a:hover{background:#e9e6dc}
nav a.call{background:var(--forest);color:#fff}
main{max-width:1120px;margin:auto;padding:0 20px}
#home section{margin:28px 0;border-radius:18px;overflow:hidden}
.hero{min-height:72vh;display:flex;flex-direction:column;justify-content:flex-end;padding:56px max(24px,5vw);color:#fff;background:linear-gradient(180deg,rgba(20,30,22,.05),rgba(20,30,22,.72)),var(--forest) center/cover no-repeat}
.hero h1{font-size:clamp(32px,6vw,58px);margin-bottom:.4em}
.hero .kicker{letter-spacing:.18em;font-size:13px;opacity:.9;margin:0 0 10px}
.hero .lead{max-width:34em;font-size:17px;opacity:.95}
.btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
.btn{display:inline-block;background:#fff;color:var(--forest)!important;text-decoration:none;font-weight:700;padding:12px 22px;border-radius:999px}
.btn.ghost{background:transparent;color:#fff!important;border:1.5px solid rgba(255,255,255,.8)}
.three{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;border-radius:0!important;overflow:visible!important}
.card{background:var(--paper);border:1px solid var(--line);border-radius:16px;overflow:hidden}
.card::before{content:'';display:block;aspect-ratio:4/3;background:#dfe5d6 center/cover no-repeat;background-image:var(--img,none)}
.card .tag{margin:16px 18px 0;font-size:12px;letter-spacing:.14em;color:var(--moss);font-weight:700}
.card h3{margin:4px 18px 6px;font-size:21px}.card p{margin:0 18px 18px;color:var(--sub);font-size:15px}
.story,.stay{display:grid;grid-template-columns:1.1fr 1fr;background:var(--paper);border:1px solid var(--line)}
.story::before,.stay::before{content:'';min-height:340px;background:#d9e1d1 center/cover no-repeat;background-image:var(--img,none)}
.story>*,.stay>*{grid-column:2;padding:0 36px}.story h2,.stay h2{padding-top:36px;font-size:28px}
.story>*:last-child,.stay>*:last-child{padding-bottom:36px}
.stay{grid-template-columns:1fr 1.1fr}.stay::before{grid-column:2;grid-row:1/span 9}.stay>*{grid-column:1}
.stay .btn{background:var(--forest);color:#fff!important}
.contact{background:var(--forest);color:#fff;text-align:center;padding:52px 24px}
.contact .big,.page .big{font-family:'Noto Serif KR',serif;font-size:clamp(28px,5vw,40px);font-weight:700;margin:.2em 0;letter-spacing:.04em}
.page-head{margin:28px 0 0;border-radius:18px;min-height:260px;display:flex;align-items:flex-end;padding:36px;color:#fff;background:linear-gradient(180deg,rgba(20,30,22,0),rgba(20,30,22,.7)),var(--forest) center/cover no-repeat}
.page-head h1{font-size:clamp(28px,5vw,44px);margin:0}
article.single{background:var(--paper);border:1px solid var(--line);border-radius:18px;margin:20px 0 40px;padding:36px clamp(20px,5vw,64px)}
.page{max-width:720px;margin:auto}.page .lead{font-size:19px;color:var(--forest);font-weight:500}
.page h2{font-size:22px;margin-top:1.8em;padding-top:1em;border-top:1px solid var(--line)}
.page .note{background:#eef2e8;border-radius:12px;padding:14px 18px;margin-top:28px}
.items{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin:24px 0}
.item{border:1px solid var(--line);border-radius:14px;overflow:hidden}
.item::before{content:'';display:block;aspect-ratio:1/1;background:#e4e8dc center/cover no-repeat;background-image:var(--img,none)}
.item h3{margin:14px 16px 4px;font-size:19px}.item p{margin:0 16px 10px;font-size:15px;color:var(--sub)}
.item .price{color:var(--forest);font-weight:700;margin-bottom:16px}
.list{display:grid;gap:12px;margin:28px 0 48px}
.list a{display:block;background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:18px 22px;text-decoration:none}
.news h2{font-size:24px;margin:40px 0 12px}
footer{border-top:1px solid var(--line);margin-top:40px;padding:28px 20px 40px;text-align:center;color:var(--sub);font-size:14px}
.blog-pager,.post-footer,.comments{display:none}
@media(max-width:820px){.three,.items{grid-template-columns:1fr}.story,.stay{grid-template-columns:1fr}.story>*,.stay>*{grid-column:1;padding:0 22px}.stay::before{grid-column:1;grid-row:auto}.story::before,.stay::before{min-height:220px}.hero{min-height:64vh}}

body.script:
//
(function(){
function imgs(root){root.querySelectorAll('[data-img]').forEach(function(el){var u=el.getAttribute('data-img');if(/^https?:/.test(u)){el.style.setProperty('--img','url('+u+')');if(el.classList.contains('hero'))el.style.backgroundImage='linear-gradient(180deg,rgba(20,30,22,.05),rgba(20,30,22,.72)),url('+u+')';}});}
imgs(document);
var pg=document.querySelector('article.single .page');var ph=document.querySelector('.page-head');
if(pg&&ph){var u=pg.getAttribute('data-img');if(/^https?:/.test(u||''))ph.style.backgroundImage='linear-gradient(180deg,rgba(20,30,22,0),rgba(20,30,22,.7)),url('+u+')';}
var home=document.getElementById('home');if(!home)return;
function feed(label,n){return fetch('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results='+n).then(function(r){return r.json()}).then(function(j){return j.feed.entry||[]});}
feed('홈',1).then(function(e){if(e[0]){home.innerHTML=e[0].content.$t;imgs(home);}});
feed('소식',3).then(function(e){if(!e.length)return;var h='<h2>숲 소식</h2><div class="list">';e.forEach(function(x){var l=x.link.filter(function(k){return k.rel=='alternate'})[0];h+='<a href="'+l.href+'"><strong>'+x.title.$t+'</strong></a>';});document.getElementById('news').innerHTML=h+'</div>';});
})();
//
